#!/usr/bin/env node
/**
 * Safe SSH runner for the LIVE Soul Pilates box (51.79.226.200).
 * - Decrypts server.rootPasswordEnc in-memory (never printed/logged).
 * - Asserts `hostname -I` contains 51.79.226.200 before running the real command.
 * - Reads the command from a file path given as argv[2] (avoids shell-quoting issues).
 * Usage: node sprun.js /path/to/remote-cmd.sh
 */
const fs = require("fs");
const path = require("path");
const { createDecipheriv, scryptSync } = require("node:crypto");

const NXEON = "/opt/nxeon";
const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const EXPECT_IP = "51.79.226.200";

// Load AUTH_SECRET from /opt/nxeon/.env without polluting env output.
function loadEnv() {
  const raw = fs.readFileSync(path.join(NXEON, ".env"), "utf8");
  const out = {};
  for (const line of raw.split("\n")) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
    if (m) {
      let v = m[2];
      if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
      out[m[1]] = v;
    }
  }
  return out;
}

function decryptSecret(enc, secret) {
  if (!enc) return null;
  try {
    const key = scryptSync(secret, "nxeon-byok", 32);
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const decipher = createDecipheriv("aes-256-gcm", key, Buffer.from(ivB64, "base64"));
    decipher.setAuthTag(Buffer.from(tagB64, "base64"));
    return Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]).toString("utf8");
  } catch (e) {
    return null;
  }
}

(async () => {
  const cmdFile = process.argv[2];
  if (!cmdFile) { console.error("no command file"); process.exit(2); }
  const remoteCmd = fs.readFileSync(cmdFile, "utf8");

  const env = loadEnv();
  const authSecret = env.AUTH_SECRET;
  if (!authSecret) { console.error("AUTH_SECRET missing"); process.exit(2); }

  const { PrismaClient } = require(path.join(NXEON, "node_modules/@prisma/client"));
  const db = new PrismaClient();
  const server = await db.server.findUnique({ where: { id: SERVER_ID }, select: { rootPasswordEnc: true, rootPassword: true } });
  await db.$disconnect();
  if (!server) { console.error("server not found"); process.exit(2); }
  const password = decryptSecret(server.rootPasswordEnc, authSecret) || server.rootPassword;
  if (!password) { console.error("no password"); process.exit(2); }

  const { Client } = require(path.join(NXEON, "node_modules/ssh2"));
  const conn = new Client();

  function exec(command) {
    return new Promise((resolve, reject) => {
      conn.exec(command, (err, stream) => {
        if (err) return reject(err);
        let out = "", errOut = "";
        stream.on("close", (code) => resolve({ code, out, errOut }));
        stream.on("data", (d) => (out += d.toString()));
        stream.stderr.on("data", (d) => (errOut += d.toString()));
      });
    });
  }

  conn.on("ready", async () => {
    try {
      // Guard: assert we are on the correct box BEFORE the real command.
      const check = await exec("hostname -I");
      if (!check.out.includes(EXPECT_IP)) {
        console.error("SAFETY ABORT: remote host does not contain " + EXPECT_IP + " -> " + check.out.trim());
        conn.end();
        process.exit(3);
      }
      const res = await exec(remoteCmd);
      process.stdout.write(res.out);
      if (res.errOut) process.stderr.write("\n[stderr]\n" + res.errOut);
      conn.end();
      process.exit(res.code || 0);
    } catch (e) {
      console.error("EXEC ERROR:", e.message);
      conn.end();
      process.exit(1);
    }
  });
  conn.on("error", (e) => { console.error("SSH ERROR:", e.message); process.exit(1); });
  conn.connect({ host: EXPECT_IP, port: 22, username: "root", password, readyTimeout: 20000 });
})();

