########## CustomerAuthController.cs ##########
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Interfaces;
using System;
using System.Linq;
using System.Security.Claims;
using System.Threading;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/customer")]
public class CustomerAuthController : ControllerBase
{
    private readonly ICustomerAuthService _customerAuth;
    // P1-S13: settings driver for the public cancel-policy endpoint.
    private readonly ISettingsService _settingsService;

    public CustomerAuthController(ICustomerAuthService customerAuth, ISettingsService settingsService)
    {
        _customerAuth = customerAuth;
        _settingsService = settingsService;
    }

    // ── POST /api/customer/register ────────────────────────────────────────────
    [HttpPost("register")]
    [AllowAnonymous]
    [EnableRateLimiting("auth-register")] // P4-S12: 5 req / 60s per IP.
    public async Task<IActionResult> Register([FromBody] CustomerRegisterRequest req)
    {
        if (string.IsNullOrWhiteSpace(req.Email) || string.IsNullOrWhiteSpace(req.Password) || string.IsNullOrWhiteSpace(req.FullName))
            return BadRequest(new { message = "Name, email and password are required." });

        if (req.Password.Length < 8)
            return BadRequest(new { message = "Password must be at least 8 characters." });

        try
        {
            var account = await _customerAuth.RegisterAsync(req.FullName, req.Email, req.Password, req.Phone, req.PhoneCountryCode);
            return Ok(new
            {
                message = account.EmailVerified
                    ? "Account created successfully."
                    : "Account created! Please check your email to verify your account.",
                emailVerificationRequired = !account.EmailVerified
            });
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    // ── POST /api/customer/login ───────────────────────────────────────────────
    [HttpPost("login")]
    [AllowAnonymous]
    [EnableRateLimiting("auth-login")] // P4-S12: 10 req / 60s per IP.
    public async Task<IActionResult> Login([FromBody] CustomerLoginRequest req)
    {
        if (string.IsNullOrWhiteSpace(req.Email) || string.IsNullOrWhiteSpace(req.Password))
            return BadRequest(new { message = "Email and password are required." });

        var result = await _customerAuth.LoginAsync(req.Email, req.Password);
        if (result == null)
            return Unauthorized(new { message = "Invalid email or password, or email not verified." });

        var (token, account) = result.Value;
        return Ok(new
        {
            token,
            fullName = account.FullName,
            email = account.Email,
            clientId = account.ClientId,
            emailVerified = account.EmailVerified
        });
    }

    // ── GET /api/customer/verify-email?token= ─────────────────────────────────
    [HttpGet("verify-email")]
    [AllowAnonymous]
    [EnableRateLimiting("auth-login")] // P4-S12: shares the auth-login 10/60s bucket.
    public async Task<IActionResult> VerifyEmail([FromQuery] string token)
    {
        if (string.IsNullOrWhiteSpace(token))
            return BadRequest(new { message = "Token is required." });

        var success = await _customerAuth.VerifyEmailAsync(token);
        if (!success)
            return BadRequest(new { message = "Invalid or expired verification token." });

        return Ok(new { message = "Email verified successfully! You can now log in." });
    }

    // ── GET /api/customer/me ───────────────────────────────────────────────────
    [HttpGet("me")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> Me()
    {
        var accountId = User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (accountId == null) return Unauthorized();

        var account = await _customerAuth.GetAccountByIdAsync(accountId);
        if (account == null) return NotFound();

        return Ok(new
        {
            account.Id,
            account.FullName,
            account.Email,
            account.PhoneNumber,
            account.CountryOfOrigin,
            account.ClientId,
            account.EmailVerified,
            account.OnboardingCompleted,
            account.DateOfBirth,
            account.MedicalHistory,
            account.ReferralSource,
            account.CreatedAt
        });
    }

    // ── GET /api/customer/my-bookings ─────────────────────────────────────────
    [HttpGet("my-bookings")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> MyBookings()
    {
        var clientId = User.FindFirstValue("clientId");
        if (string.IsNullOrWhiteSpace(clientId)) return Ok(Array.Empty<object>());

        var bookings = await _customerAuth.GetMyBookingsEnrichedAsync(clientId);
        return Ok(bookings);
    }

    // ── POST /api/customer/cancel-booking/{id} ────────────────────────────────
    /// <summary>
    /// Cancel a booking. SPM-110: an optional body may carry
    /// <see cref="CancelBookingRequest.SeatsToCancel"/> to release only some seats
    /// of a multi-seat group booking. Omitting the body (or passing a count that
    /// meets/exceeds the booking's Quantity) performs the legacy full cancel, so
    /// existing callers are unaffected.
    /// </summary>
    [HttpPost("cancel-booking/{attendanceId}")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> CancelBooking(string attendanceId, [FromBody] CancelBookingRequest? req = null)
    {
        var clientId = User.FindFirstValue("clientId");
        if (string.IsNullOrWhiteSpace(clientId)) return Unauthorized();

        try
        {
            var result = await _customerAuth.CancelBookingAsync(clientId, attendanceId, req?.SeatsToCancel);
            return Ok(result);
        }
        catch (UnauthorizedAccessException ex)
        {
            // P1-S13: distinct from a failed-auth 401 - the JWT is valid but the
            // resource isn't theirs. Maps to spec's "403 if attendance.ClientId mismatch".
            return StatusCode(403, new { message = ex.Message });
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpGet("cancel-policy")]
    [AllowAnonymous]
    public async Task<IActionResult> CancelPolicy(CancellationToken ct)
    {
        var settings = await _settingsService.GetAsync(ct);
        return Ok(new
        {
            // Legacy fields (kept for backward compat with older clients)
            cancelWindowHoursGroup = settings.CancelWindowHoursGroup,
            cancelWindowHoursPrivate = settings.CancelWindowHoursPrivate,
            // Per-payment-method windows
            cancelWindowHoursCreditGroup = settings.CancelWindowHoursCreditGroup,
            cancelWindowHoursCreditPrivate = settings.CancelWindowHoursCreditPrivate,
            cancelWindowHoursOnlineGroup = settings.CancelWindowHoursOnlineGroup,
            cancelWindowHoursOnlinePrivate = settings.CancelWindowHoursOnlinePrivate,
            cancelWindowHoursStudioGroup = settings.CancelWindowHoursStudioGroup,
            cancelWindowHoursStudioPrivate = settings.CancelWindowHoursStudioPrivate,
            // Reschedule configuration
            enableLateReschedule = settings.EnableLateReschedule,
            lateRescheduleMaxPerMonth = settings.LateRescheduleMaxPerMonth,
            lateRescheduleMode = settings.LateRescheduleMode,
            lateRescheduleEligibleMethods = settings.LateRescheduleEligibleMethods,
            // P4-S02: Waitlist master switch — tells the booking page whether to show the join-waitlist CTA.
            enableWaitlistSystem = settings.EnableWaitlistSystem,
            // Customer sign-up email verification toggle — tells the register/success page
            // whether to show the "check your email" state vs auto-login.
            enableSignUpEmailVerification = settings.EnableSignUpEmailVerification,
            // Guest checkout toggle — booking page uses this to gate the Book button
            // without requiring a separate settings fetch.
            allowGuestCheckout = settings.AllowGuestCheckout,
        });
    }


    // ── POST /api/customer/reschedule-booking/{attendanceId} ──────────────────
    [HttpPost("reschedule-booking/{attendanceId}")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> RescheduleBooking(string attendanceId, [FromBody] RescheduleRequest req)
    {
        var clientId = User.FindFirstValue("clientId");
        if (string.IsNullOrWhiteSpace(clientId)) return Unauthorized();

        if (string.IsNullOrWhiteSpace(req.NewSessionId))
            return BadRequest(new { message = "NewSessionId is required." });

        try
        {
            var result = await _customerAuth.RescheduleBookingAsync(clientId, attendanceId, req.NewSessionId);
            return Ok(result);
        }
        catch (UnauthorizedAccessException ex)
        {
            return StatusCode(403, new { message = ex.Message });
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    // ── GET /api/customer/reschedule-eligibility ──────────────────────────────
    [HttpGet("reschedule-eligibility")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> RescheduleEligibility()
    {
        var clientId = User.FindFirstValue("clientId");
        if (string.IsNullOrWhiteSpace(clientId)) return Unauthorized();

        var (eligible, remaining, max) = await _customerAuth.GetRescheduleEligibilityAsync(clientId);
        return Ok(new { eligible, remaining, max });
    }

    // ── POST /api/customer/reset-reschedule-grace/{clientId} ─────────────────
    /// <summary>
    /// Admin-only: reset a client's late-reschedule grace from the admin
    /// client profile. The <c>clientId</c> param is the CRM Client.Id,
    /// NOT the CustomerAccount.Id.
    /// </summary>
    [HttpPost("reset-reschedule-grace/{clientId}")]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> ResetRescheduleGrace(string clientId)
    {
        var ok = await _customerAuth.ResetRescheduleGraceAsync(clientId);
        if (!ok) return NotFound(new { message = "Customer account not found." });
        return Ok(new { success = true, message = "Reschedule grace has been reset." });
    }

    // ── GET /api/customer/my-packages ─────────────────────────────────────────
    [HttpGet("my-packages")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> MyPackages()
    {
        var clientId = User.FindFirstValue("clientId");
        if (string.IsNullOrWhiteSpace(clientId)) return Ok(Array.Empty<object>());

        var packages = await _customerAuth.GetMyPackagesAsync(clientId);
        return Ok(packages.Select(p => new
        {
            p.Id,
            p.Format,
            p.TotalCredits,
            p.CreditsUsed,
            p.CreditsRemaining,
            p.ActivationDate,
            p.ExpiryDate,
            p.Status,
            p.FractionalValuePerClass
        }));
    }

    // ── PUT /api/customer/profile ──────────────────────────────────────────────
    [HttpPut("profile")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> UpdateProfile([FromBody] CustomerProfileRequest req)
    {
        var accountId = User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (accountId == null) return Unauthorized();

        var success = await _customerAuth.UpdateProfileAsync(accountId, req.FullName, req.Phone, req.Country);
        if (!success) return NotFound();
        return Ok(new { message = "Profile updated." });
    }

    // ── POST /api/customer/onboarding ────────────────────────────────────
    [HttpPost("onboarding")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> CompleteOnboarding([FromBody] OnboardingRequest req)
    {
        var accountId = User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (accountId == null) return Unauthorized();

        await _customerAuth.CompleteOnboardingAsync(accountId, req.DateOfBirth, req.MedicalHistory, req.ReferralSource);
        return Ok(new { message = "Onboarding complete." });
    }

    // ── POST /api/customer/forgot-password ─────────────────────────────────────
    /// <summary>
    /// Anti-enumeration password-reset request endpoint. Always returns 200
    /// with a generic message regardless of whether the email belongs to a
    /// registered account. Rate-limited under the existing auth-register
    /// bucket (5 req / 60s / IP) to mute scripted enumeration attempts even
    /// though the response itself doesn't leak.
    /// </summary>
    [HttpPost("forgot-password")]
    [AllowAnonymous]
    [EnableRateLimiting("auth-register")]
    public async Task<IActionResult> ForgotPassword([FromBody] ForgotPasswordRequest req)
    {
        if (string.IsNullOrWhiteSpace(req.Email))
            return BadRequest(new { message = "Email is required." });

        await _customerAuth.RequestPasswordResetAsync(req.Email);

        // Generic response shape — DO NOT leak whether the email exists.
        // The service is also anti-enumeration internally; this is defence
        // in depth so a future refactor can't accidentally drop the guard.
        return Ok(new
        {
            message = "If an account exists for that email, a reset link is on its way. Please check your inbox."
        });
    }

    // ── POST /api/customer/reset-password ──────────────────────────────────────
    /// <summary>
    /// Consume a password-reset token from the user's email and rotate the
    /// password. Same rate-limit bucket as forgot-password — these flows
    /// share a single brute-force surface.
    /// </summary>
    [HttpPost("reset-password")]
    [AllowAnonymous]
    [EnableRateLimiting("auth-register")]
    public async Task<IActionResult> ResetPassword([FromBody] ResetPasswordRequest req)
    {
        if (string.IsNullOrWhiteSpace(req.Token))
            return BadRequest(new { message = "Reset token is required." });
        if (string.IsNullOrWhiteSpace(req.NewPassword))
            return BadRequest(new { message = "New password is required." });
        if (req.NewPassword.Length < 8)
            return BadRequest(new { message = "Password must be at least 8 characters." });

        var ok = await _customerAuth.ResetPasswordAsync(req.Token, req.NewPassword);
        if (!ok)
        {
            return BadRequest(new
            {
                message = "This reset link is invalid or has expired. Please request a new one."
            });
        }

        return Ok(new { message = "Your password has been reset. You can now log in with your new password." });
    }
}

