81	        // persistence so new accounts are stored consistently. This is what makes
82	        // the case-insensitive reset lookup reliable for accounts created from here
83	        // onward, and it tightens the duplicate check so "Foo@x.com" and
84	        // "foo@x.com" can't both register.
85	        email = (email ?? string.Empty).Trim().ToLowerInvariant();
86	
87	        // Duplicate check. SPM-94: email is force-lowercased above, but EXISTING
88	        // accounts may store a mixed-case email, so an exact-match equality misses
89	        // them and a second account is created (after which case-insensitive login
90	        // resolves nondeterministically). Match case-insensitively using the same
91	        // anchored, escaped 'i' regex LoginAsync/RequestPasswordResetAsync use.
92	        var emailPattern = new MongoDB.Bson.BsonRegularExpression(
93	            $"^{System.Text.RegularExpressions.Regex.Escape(email)}$", "i");
94	        var exists = await _accounts
95	            .Find(Builders<CustomerAccount>.Filter.Regex(a => a.Email, emailPattern))
96	            .FirstOrDefaultAsync();
97	        if (exists != null) throw new Exception("An account with this email already exists.");
98	
99	        // Duplicate phone check — an account is a single person's contact number, so
100	        // block a second account on the same phone. Compares by significant digits so
101	        // it catches both national ("901234567") and full ("+84901234567") storage
102	        // forms. Filler/placeholder numbers are skipped (see IsPlaceholderPhone).
103	        if (!string.IsNullOrWhiteSpace(phone) && !IsPlaceholderPhone(phone))
104	        {
105	            var target = SignificantPhoneDigits(phone);
106	            if (!string.IsNullOrEmpty(target))
107	            {
108	                var accountPhones = await _accounts
109	                    .Find(Builders<CustomerAccount>.Filter.And(
110	                        Builders<CustomerAccount>.Filter.Ne(a => a.PhoneNumber, null),
111	                        Builders<CustomerAccount>.Filter.Ne(a => a.PhoneNumber, "")))
112	                    .Project(a => a.PhoneNumber)
113	                    .ToListAsync();
114	                if (accountPhones.Any(p => SignificantPhoneDigits(p) == target))
115	                    throw new Exception("An account with this phone number already exists.");
116	            }
117	        }
118	
119	        // Auto-link to existing Client record (phone first, then email).
120	        // P2-S13: phone may arrive in either pre-split form (e.g. "+84901234567",
121	        // typical for older clients), or in post-split form (e.g. national
122	        // "901234567" + phoneCountryCode "+84"). Match against both
123	        // representations.
124	        string? clientId = null;
125	        Client? linked = null;
126	
127	        // Skip phone-matching for filler/placeholder numbers (e.g. 999999999,
128	        // 000000000, sequential): otherwise two unrelated people who both entered
129	        // a junk phone get linked to the SAME client and see each other's bookings.
130	        if (!string.IsNullOrWhiteSpace(phone) && !IsPlaceholderPhone(phone))
131	        {
132	            // Direct match against PhoneNumber (works for both forms).
133	            linked = await _clients.Find(c => c.PhoneNumber == phone).FirstOrDefaultAsync();
134	
135	            // If we got the split form from the form, try matching the
136	            // (countryCode, national) pair against the entity's two fields.
137	            if (linked == null && !string.IsNullOrWhiteSpace(phoneCountryCode))
138	            {
139	                linked = await _clients
140	                    .Find(c => c.PhoneCountryCode == phoneCountryCode && c.PhoneNumber == phone)
141	                    .FirstOrDefaultAsync();
142	            }
143	        }
144	
145	        if (linked == null)
146	            // SPM-94: email is force-lowercased above, but an EXISTING Client may
147	            // store a mixed-case email. An exact-match equality misses it and a
148	            // DUPLICATE Client gets created. Match case-insensitively with the same
149	            // anchored, escaped 'i' regex used for the account lookup above.
150	            linked = await _clients
151	                .Find(Builders<Client>.Filter.Regex(c => c.Email, emailPattern))
152	                .FirstOrDefaultAsync();
153	
154	        if (linked != null)
155	        {
156	            clientId = linked.Id;
157	        }
158	        else
159	        {
160	            // Auto-create CRM Client record. Persist the split form when we
161	            // have it; otherwise fall back to dumping the raw value into
162	            // PhoneNumber (the migration command can split it later).
163	            var newClient = new Client
164	            {
165	                FullName = fullName,
166	                Email = email,
167	                PhoneNumber = phone,
168	                PhoneCountryCode = phoneCountryCode,
169	                ContactPlatform = "EMAIL"
170	            };
171	            await _clients.InsertOneAsync(newClient);
172	            clientId = newClient.Id;
173	        }
174	
175	        var emailVerifyEnabled = await IsEmailVerifyEnabledAsync();
176	        var verificationToken = Guid.NewGuid().ToString("N");
177	        var account = new CustomerAccount
178	        {
179	            FullName = fullName,
180	            Email = email,
181	            PasswordHash = PasswordHasher.Hash(password),
182	            // CustomerAccount keeps a single phone field (not split) — it's
183	            // primarily the contact channel, not a CRM record. The CRM
184	            // Client carries the split form.
185	            PhoneNumber = phone,
186	            ClientId = clientId,
187	            // If email verify is disabled, auto-verify; otherwise send email
188	            EmailVerified = !emailVerifyEnabled,
189	            EmailVerificationToken = emailVerifyEnabled ? verificationToken : null,
190	            EmailVerificationExpiry = emailVerifyEnabled ? DateTime.UtcNow.AddHours(24) : null
191	        };
192	
193	        await _accounts.InsertOneAsync(account);
194	
195	        // Send verification email if enabled
196	        if (emailVerifyEnabled)
197	        {
198	            await _emailService.SendVerificationEmailAsync(email, fullName, verificationToken);
199	        }
200	
201	        return account;
202	    }
