using SoulPilates.Core.Entities;
using SoulPilates.Core.DTOs;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace SoulPilates.Core.Interfaces;

public interface ICustomerAuthService
{
    Task<CustomerAccount> RegisterAsync(string fullName, string email, string password, string? phone, string? phoneCountryCode = null);

    /// <summary>
    /// Returns "email" or "phone" if that identifier already belongs to a registered
    /// account, else null. Used to prompt a guest who already has an account to log in.
    /// </summary>
    Task<string?> MatchExistingAccountAsync(string? email, string? phone);
    Task<(string token, CustomerAccount account)?> LoginAsync(string email, string password);
    Task<bool> VerifyEmailAsync(string token);
    Task<CustomerAccount?> GetAccountByIdAsync(string accountId);
    Task<CustomerAccount?> GetAccountByClientIdAsync(string clientId);
    Task<IEnumerable<Attendance>> GetMyBookingsAsync(string clientId);
    Task<IEnumerable<object>> GetMyBookingsEnrichedAsync(string clientId);
    /// <summary>
    /// Cancel a booking via customer self-service. SPM-110: pass
    /// <paramref name="seatsToCancel"/> to release only some seats of a
    /// multi-seat group booking; null (or a value ≥ the booking's Quantity)
    /// performs the legacy FULL cancel.
    /// </summary>
    Task<object> CancelBookingAsync(string clientId, string attendanceId, int? seatsToCancel = null);
    Task<IEnumerable<ClientPackage>> GetMyPackagesAsync(string clientId);
    Task<bool> UpdateProfileAsync(string accountId, string fullName, string? phone, string? country);
    Task<bool> CompleteOnboardingAsync(string accountId, DateTime? dateOfBirth, string? medicalHistory, string? referralSource);

    /// <summary>
    /// Kicks off the password-reset flow for the given email. Anti-enumeration:
    /// the caller cannot distinguish a known address from an unknown one — both
    /// resolve to <c>true</c>. When the email exists, a single-use token is
    /// persisted (24h TTL) and the reset email is dispatched.
    /// </summary>
    Task<bool> RequestPasswordResetAsync(string email);

    /// <summary>
    /// Completes the password-reset flow. Returns <c>true</c> when the token
    /// matched an account and the password was rotated; <c>false</c> for
    /// missing, expired or already-used tokens. On success the token is
    /// cleared so it cannot be replayed.
    /// </summary>
    Task<bool> ResetPasswordAsync(string token, string newPassword);

    /// <summary>
    /// Migration: bulk-create portal accounts for existing clients and email a
    /// 30-day activation link ("set your password to activate"). Idempotent —
    /// clients that already have an account are skipped unless <paramref name="resend"/>
    /// re-issues a token to still-unverified accounts. Use <paramref name="onlyClientId"/>
    /// or <paramref name="onlyEmail"/> to target a single record for testing.
    /// </summary>
    Task<ActivationInviteResult> SendActivationInvitesAsync(string? onlyClientId, string? onlyEmail, bool resend);

    // ── Late Reschedule ──────────────────────────────────────────────────────────

    /// <summary>
    /// Reschedule a booking to a different session during the late-cancel window
    /// instead of forfeiting the credit/payment. Returns a result object with
    /// success/failure details and the new attendance ID.
    /// </summary>
    Task<object> RescheduleBookingAsync(string clientId, string attendanceId, string newSessionId);

    /// <summary>
    /// Checks whether the customer is currently eligible for a late reschedule
    /// (based on their account-level or booking-level usage against the configured limit).
    /// Returns the eligibility flag plus remaining count.
    /// </summary>
    Task<(bool eligible, int remaining, int max)> GetRescheduleEligibilityAsync(string clientId);

    /// <summary>
    /// Admin action: reset the customer's late-reschedule grace so they can
    /// reschedule again this month. Callable from the admin client-profile page.
    /// </summary>
    Task<bool> ResetRescheduleGraceAsync(string clientId);
}

