    <script>
      import { translatePage, getLocale, setLocale, t } from "../i18n/index.js";
      const API = import.meta.env.PUBLIC_API_URL;

      translatePage();

      // Language toggle
      document.querySelectorAll(".sp-lang-pill").forEach((b) => {
        if (b.dataset.lang === getLocale()) b.classList.add("active");
        b.addEventListener("click", () => {
          setLocale(b.dataset.lang);
          window.location.reload();
        });
      });

      // Auto-redirect if already logged in
      if (localStorage.getItem("customer_token")) {
        const redirect =
          new URLSearchParams(window.location.search).get("redirect") ||
          "/account";
        window.location.href = redirect;
      }

      // ── Contextual banner: show when arriving from booking/checkout ──
      const params = new URLSearchParams(window.location.search);
      const redirectTarget = params.get("redirect") || "";
      const isBookingRedirect =
        redirectTarget.includes("/checkout") ||
        redirectTarget.includes("/booking") ||
        redirectTarget.includes("/packages");
      if (isBookingRedirect) {
        const banner = document.getElementById("bookingContextBanner");
        if (banner) banner.style.display = "block";
      }

      // ── Propagate redirect param to Sign Up link ──
      const signUpLink = document.getElementById("signUpLink");
      if (signUpLink) {
        const signUpRedirect = params.get("redirect");
        if (signUpRedirect) {
          signUpLink.href = "/register?redirect=" + encodeURIComponent(signUpRedirect);
        }
      }

      // ── Guest checkout toggle: show "Continue as Guest" only if enabled ──
      // Both elements start hidden in the HTML to avoid a flash-of-content
      // before the API responds. We reveal them only when explicitly enabled.
      fetch(`${API}/api/payment/checkout-settings`)
        .then((r) => r.ok ? r.json() : null)
        .then((cfg) => {
          if (!cfg) return;
          if (cfg.allowGuestCheckout === true) {
            const guestBtn = document.getElementById("continueAsGuestBtn");
            const guestDivider = document.getElementById("guestDivider");
            if (guestBtn) guestBtn.style.display = "";
            if (guestDivider) guestDivider.style.display = "";
          }
        })
        .catch(() => {});
      document
        .getElementById("loginForm")
        .addEventListener("submit", async (e) => {
          e.preventDefault();
          const email = document.getElementById("email").value.trim();
          const password = document.getElementById("password").value;
          if (!email || !password) return showError(t("common.error"));

          const btn = document.getElementById("btnLogin");
          btn.disabled = true;
          const orig = btn.innerHTML;
          btn.innerHTML = "<span>...</span>";

          try {
            const res = await fetch(API + "/api/customer/login", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ email, password }),
            });
            const data = await res.json();
            if (!res.ok) {
              showError(data.message || t("common.error"));
              return;
            }

            localStorage.setItem("customer_token", data.token);
            localStorage.setItem("customer_name", data.fullName);
            localStorage.setItem("customer_email", data.email);
            localStorage.setItem("customer_clientId", data.clientId || "");

            // GA4: successful login
            if (typeof window.spTrackEvent === 'function') {
              window.spTrackEvent('login', { method: 'email', page: 'login' });
            }

            // Check onboarding status to decide where to land
            try {
              const meRes = await fetch(API + "/api/customer/me", {
                headers: { Authorization: "Bearer " + data.token },
              });
              const me = await meRes.json();
              const redirect = new URLSearchParams(window.location.search).get(
                "redirect",
              );
              if (redirect) {
                window.location.href = redirect;
                return;
              }
              if (me && me.onboardingCompleted === false) {
                window.location.href = "/onboarding";
                return;
              }
              window.location.href = "/account";
            } catch {
              window.location.href = "/account";
            }
          } catch (err) {
            showError("Network error. Please try again.");
          } finally {
            btn.disabled = false;
            btn.innerHTML = orig;
          }
        });

      function showError(msg) {
        const el = document.getElementById("errorMsg");
        el.textContent = msg;
        el.classList.add("visible");
        setTimeout(() => el.classList.remove("visible"), 5000);
      }
    </script>

    <!-- GA4 Loader (standalone page) -->
    <script is:inline>
      (function() {
        fetch('/api/analytics/ga-config')
          .then(function(r) { return r.ok ? r.json() : null; })
          .then(function(cfg) {
            if (!cfg || !cfg.measurementId) return;
            var s = document.createElement('script');
            s.async = true;
            s.src = 'https://www.googletagmanager.com/gtag/js?id=' + cfg.measurementId;
            document.head.appendChild(s);
            window.dataLayer = window.dataLayer || [];
            function gtag() { window.dataLayer.push(arguments); }
            window.gtag = gtag;
            gtag('js', new Date());
            gtag('config', cfg.measurementId, { page_path: '/login', send_page_view: true });
            window.spTrackEvent = function(e, p) {
              if (cfg.enableEventTracking !== false) gtag('event', e, p || {});
            };
          }).catch(function() {});
        if (!window.spTrackEvent) window.spTrackEvent = function() {};

        // Track Continue as Guest click (use id for reliability)
        var guestBtn = document.getElementById('continueAsGuestBtn');
        if (guestBtn) {
          guestBtn.addEventListener('click', function() {
            if (typeof window.spTrackEvent === 'function') {
              window.spTrackEvent('continue_as_guest', { page: 'login' });
            }
          });
        }
      })();
    </script>
