373	/// <summary>
374	/// Resolve the upstream client IP for rate-limit partitioning. Reads from
375	/// <c>Connection.RemoteIpAddress</c>, which the ForwardedHeaders middleware
376	/// (configured upstream of <c>UseRateLimiter</c>) has already populated with
377	/// the real client IP from the reverse proxy. Falls back to a sentinel
378	/// <c>"unknown"</c> partition if neither is available, ensuring even oddly-
379	/// addressed callers share a single bucket (worst case: collective limit).
380	/// </summary>
381	static string ResolveClientIp(HttpContext context)
382	{
383	    var ip = context.Connection.RemoteIpAddress?.ToString();
384	    return string.IsNullOrWhiteSpace(ip) ? "unknown" : ip;
