// https://astro.build/config
export default defineConfig({
  // Canonical production origin — drives <link rel="canonical"> and Open Graph
  // URLs. Apex domain (post new.→apex migration).
  site: 'https://soulpilates.com.vn',
  vite: {
    environments: {
      // Astro 6 (Vite 7) reads sourcemap from the per-environment build config.
      // static-build.js: sourcemap = viteConfig.environments?.client?.build?.sourcemap ?? false
      // Setting it here causes .js.map and .css.map files to be emitted in
      // dist/_astro/ and served by the existing nginx /_astro/ block.
      client: {
