# Soul Pilates — nginx config for the static Astro bundle
server {
    listen      80 default_server;
    listen      [::]:80 default_server;
    server_name _;

    root  /usr/share/nginx/html;
    index index.html;

    # Emit relative Location headers so the outer reverse-proxy's scheme is preserved
    absolute_redirect off;

    # Long-cache the immutable build assets
    location /_astro/ {
        access_log    off;
        expires       1y;
        add_header    Cache-Control "public, immutable";
        try_files     $uri =404;
    }

    # Static media — safe to cache
    location ~* \.(png|jpg|jpeg|gif|svg|ico|webp|woff2?)$ {
        expires    7d;
        add_header Cache-Control "public";
        try_files  $uri =404;
    }

    # Astro generates directory-style routes (/booking/index.html). Try as-is
    # first; if the file doesn't exist, try the directory; fall back to 404.
    # HTML is served through here at directory URLs (no .html suffix), so the
    # no-store header must live on this location or phones cache stale pages
    # that reference old JS bundles.
    location / {
        add_header Cache-Control "no-store, must-revalidate";
        add_header Pragma "no-cache";
        add_header X-Content-Type-Options nosniff;
        add_header X-Frame-Options SAMEORIGIN;
        add_header Referrer-Policy strict-origin-when-cross-origin;
        try_files $uri $uri/ $uri.html /404.html;
    }

    # Reasonable security defaults
    add_header X-Content-Type-Options nosniff;
    add_header X-Frame-Options SAMEORIGIN;
    add_header Referrer-Policy strict-origin-when-cross-origin;
}
