namespace SoulPilates.Core.Configuration;

/// <summary>
/// Google OAuth 2.0 (authorization-code flow) configuration. Bound from the
/// <c>GoogleAuth</c> config section, which the container populates from the
/// <c>GOOGLE_CLIENT_ID</c> / <c>GOOGLE_CLIENT_SECRET</c> / <c>GOOGLE_REDIRECT_URI</c>
/// environment variables (see docker-compose <c>GoogleAuth__*</c> mappings).
///
/// SELF-GATING: when <see cref="ClientId"/> or <see cref="ClientSecret"/> is
/// blank the feature is considered disabled — the API routes no-op (404) and
/// the frontend hides the "Continue with Google" button. This lets the code
/// ship dark and light up the moment real credentials are added, with no
/// redeploy of logic.
/// </summary>
public class GoogleAuthSettings
{
    public string? ClientId { get; set; }
    public string? ClientSecret { get; set; }

    /// <summary>
    /// The OAuth redirect/callback URI registered in Google Cloud Console. Must
    /// exactly match, e.g. <c>https://soulpilates.com.vn/api/customer/google/callback</c>
    /// (prod) or <c>https://staging.soulpilates.com.vn/api/customer/google/callback</c>
    /// (staging). If left blank the service derives it from the incoming request
    /// origin + <c>/api/customer/google/callback</c>.
    /// </summary>
    public string? RedirectUri { get; set; }

    /// <summary>True only when both client id and secret are present.</summary>
    public bool IsConfigured =>
        !string.IsNullOrWhiteSpace(ClientId) && !string.IsNullOrWhiteSpace(ClientSecret);
}

using System.Threading;
using System.Threading.Tasks;

namespace SoulPilates.Core.Interfaces;

/// <summary>
/// Minimal Google OAuth 2.0 authorization-code client. Builds the consent-screen
/// URL and exchanges the returned <c>code</c> for a verified user identity.
/// Deliberately dependency-free (no Google.Apis.Auth NuGet) — the id_token is
/// received directly from Google's token endpoint over a server-to-server TLS
/// call authenticated with our client secret, so we validate its
/// <c>aud</c>/<c>iss</c>/<c>exp</c> claims and trust it without re-fetching JWKS.
/// </summary>
public interface IGoogleOAuthService
{
    /// <summary>Whether a client id + secret are configured (feature self-gate).</summary>
    bool IsConfigured { get; }

    /// <summary>
    /// Resolve the exact redirect URI Google will call back. Prefers the
    /// configured <c>GoogleAuth:RedirectUri</c>; otherwise derives it from the
    /// public origin as <c>{origin}/api/customer/google/callback</c>.
    /// </summary>
    string ResolveRedirectUri(string publicOrigin);

    /// <summary>Build the Google consent-screen URL to redirect the browser to.</summary>
    string BuildAuthorizationUrl(string state, string redirectUri);

    /// <summary>
    /// Exchange an authorization <c>code</c> for the caller's verified identity.
    /// Returns null if the exchange fails or the id_token doesn't validate.
    /// </summary>
    Task<GoogleUserInfo?> ExchangeCodeAsync(string code, string redirectUri, CancellationToken ct = default);
}

/// <summary>Verified identity claims extracted from a Google id_token.</summary>
public class GoogleUserInfo
{
    /// <summary>Stable Google subject id (the <c>sub</c> claim).</summary>
    public string Sub { get; set; } = null!;
    public string Email { get; set; } = null!;
    public bool EmailVerified { get; set; }
    public string? Name { get; set; }
}

using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// Dependency-free Google OAuth 2.0 authorization-code client. See
/// <see cref="IGoogleOAuthService"/> for the security rationale.
/// </summary>
public class GoogleOAuthService : IGoogleOAuthService
{
    private const string AuthEndpoint  = "https://accounts.google.com/o/oauth2/v2/auth";
    private const string TokenEndpoint = "https://oauth2.googleapis.com/token";

    private readonly IHttpClientFactory _httpFactory;
    private readonly GoogleAuthSettings _settings;
    private readonly ILogger<GoogleOAuthService> _logger;

    public GoogleOAuthService(
        IHttpClientFactory httpFactory,
        IOptions<GoogleAuthSettings> settings,
        ILogger<GoogleOAuthService> logger)
    {
        _httpFactory = httpFactory;
        _settings = settings.Value;
        _logger = logger;
    }

    public bool IsConfigured => _settings.IsConfigured;

    public string ResolveRedirectUri(string publicOrigin)
    {
        if (!string.IsNullOrWhiteSpace(_settings.RedirectUri))
            return _settings.RedirectUri!.Trim();
        return $"{publicOrigin.TrimEnd('/')}/api/customer/google/callback";
    }

    public string BuildAuthorizationUrl(string state, string redirectUri)
    {
        var q = new Dictionary<string, string>
        {
            ["client_id"] = _settings.ClientId!,
            ["redirect_uri"] = redirectUri,
            ["response_type"] = "code",
            ["scope"] = "openid email profile",
            ["state"] = state,
            ["access_type"] = "online",
            ["include_granted_scopes"] = "true",
            ["prompt"] = "select_account",
        };
        var qs = string.Join("&", System.Linq.Enumerable.Select(q,
            kv => $"{Uri.EscapeDataString(kv.Key)}={Uri.EscapeDataString(kv.Value)}"));
        return $"{AuthEndpoint}?{qs}";
    }

    public async Task<GoogleUserInfo?> ExchangeCodeAsync(string code, string redirectUri, CancellationToken ct = default)
    {
        if (!IsConfigured)
            return null;

        try
        {
            var client = _httpFactory.CreateClient("google-oauth");
            var form = new FormUrlEncodedContent(new Dictionary<string, string>
            {
                ["code"] = code,
                ["client_id"] = _settings.ClientId!,
                ["client_secret"] = _settings.ClientSecret!,
                ["redirect_uri"] = redirectUri,
                ["grant_type"] = "authorization_code",
            });

            using var resp = await client.PostAsync(TokenEndpoint, form, ct);
            var body = await resp.Content.ReadAsStringAsync(ct);
            if (!resp.IsSuccessStatusCode)
            {
                _logger.LogWarning("Google token exchange failed ({Status}): {Body}", (int)resp.StatusCode, body);
                return null;
            }

            using var doc = JsonDocument.Parse(body);
            if (!doc.RootElement.TryGetProperty("id_token", out var idTokenEl))
            {
                _logger.LogWarning("Google token response had no id_token.");
                return null;
            }

            var idToken = idTokenEl.GetString();
            if (string.IsNullOrWhiteSpace(idToken))
                return null;

            return ParseAndValidateIdToken(idToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Google OAuth code exchange threw.");
            return null;
        }
    }

    /// <summary>
    /// Decode the id_token payload and validate aud/iss/exp. Signature is not
    /// re-verified because the token came directly from Google's token endpoint
    /// over TLS (per Google's OpenID Connect guidance for the code flow).
    /// </summary>
    private GoogleUserInfo? ParseAndValidateIdToken(string idToken)
    {
        var parts = idToken.Split('.');
        if (parts.Length != 3)
            return null;

        JsonElement claims;
        try
        {
            var json = Encoding.UTF8.GetString(Base64UrlDecode(parts[1]));
            claims = JsonDocument.Parse(json).RootElement;
        }
        catch
        {
            return null;
        }

        // aud must match our client id.
        var aud = claims.TryGetProperty("aud", out var audEl) ? audEl.GetString() : null;
        if (!string.Equals(aud, _settings.ClientId, StringComparison.Ordinal))
        {
            _logger.LogWarning("Google id_token aud mismatch.");
            return null;
        }

        // iss must be Google.
        var iss = claims.TryGetProperty("iss", out var issEl) ? issEl.GetString() : null;
        if (iss != "accounts.google.com" && iss != "https://accounts.google.com")
        {
            _logger.LogWarning("Google id_token iss unexpected: {Iss}", iss);
            return null;
        }

        // exp must be in the future.
        if (claims.TryGetProperty("exp", out var expEl) && expEl.TryGetInt64(out var exp))
        {
            if (DateTimeOffset.FromUnixTimeSeconds(exp) < DateTimeOffset.UtcNow.AddSeconds(-30))
            {
                _logger.LogWarning("Google id_token expired.");
                return null;
            }
        }

        var email = claims.TryGetProperty("email", out var emEl) ? emEl.GetString() : null;
        var sub = claims.TryGetProperty("sub", out var subEl) ? subEl.GetString() : null;
        if (string.IsNullOrWhiteSpace(email) || string.IsNullOrWhiteSpace(sub))
            return null;

        // email_verified may arrive as a bool or a "true"/"false" string.
        var emailVerified = false;
        if (claims.TryGetProperty("email_verified", out var evEl))
        {
            emailVerified = evEl.ValueKind == JsonValueKind.True
                || (evEl.ValueKind == JsonValueKind.String && string.Equals(evEl.GetString(), "true", StringComparison.OrdinalIgnoreCase));
        }

        var name = claims.TryGetProperty("name", out var nEl) ? nEl.GetString() : null;

        return new GoogleUserInfo
        {
            Sub = sub!,
            Email = email!,
            EmailVerified = emailVerified,
            Name = name,
        };
    }

    private static byte[] Base64UrlDecode(string input)
    {
        var s = input.Replace('-', '+').Replace('_', '/');
        switch (s.Length % 4)
        {
            case 2: s += "=="; break;
            case 3: s += "="; break;
        }
        return Convert.FromBase64String(s);
    }
}

