Task<(string token, CustomerAccount account)?> LoginAsync(string email, string password);

/// <summary>
/// Sign in — or, for a first-time email, sign UP — a customer via a verified
/// Google identity, then mint the SAME JWT the password flow issues.
/// Resolution order: (1) match by <paramref name="googleId"/>; (2) match by
/// verified email and link Google to that existing (possibly password)
/// account; (3) create a brand-new Google-provisioned account auto-linked to
/// any matching CRM Client. <paramref name="emailVerified"/> MUST be true —
/// callers pass Google's <c>email_verified</c> — so an unverified Google
/// email can never hijack a password account. Returns the token, the
/// account, and whether a new account was created.
/// </summary>
Task<(string token, CustomerAccount account, bool isNewUser)> SignInWithGoogleAsync(
    string googleId, string email, bool emailVerified, string? fullName);

// ── Google Sign-in / Sign-up ───────────────────────────────────────────────
/// <inheritdoc />
public async Task<(string token, CustomerAccount account, bool isNewUser)> SignInWithGoogleAsync(
    string googleId, string email, bool emailVerified, string? fullName)
{
    if (string.IsNullOrWhiteSpace(googleId))
        throw new Exception("Missing Google account id.");
    if (string.IsNullOrWhiteSpace(email))
        throw new Exception("Google account has no email.");

    // Hard gate: Google must have verified the email. This is what prevents a
    // Google account with an unverified (spoofable) email from being linked to
    // — and thereby hijacking — an existing password account for that email.
    if (!emailVerified)
        throw new Exception("Your Google email is not verified, so it can't be used to sign in.");

    email = email.Trim().ToLowerInvariant();
    var emailPattern = new MongoDB.Bson.BsonRegularExpression(
        $"^{System.Text.RegularExpressions.Regex.Escape(email)}$", "i");

    // (1) Already-linked Google account → straight sign-in. Matching on the
    // stable googleId first means a later email change on the Google side
    // still resolves to the same local account.
    var account = await _accounts
        .Find(Builders<CustomerAccount>.Filter.Eq(a => a.GoogleId, googleId))
        .FirstOrDefaultAsync();

    if (account != null)
    {
        var t = GenerateJwt(account);
        return (t, account, false);
    }

    // (2) Existing account for this (verified) email → link Google to it.
    // Safe precisely because Google verified the email above: proof the
    // Google user controls the mailbox the password account is keyed on.
    account = await _accounts
        .Find(Builders<CustomerAccount>.Filter.Regex(a => a.Email, emailPattern))
        .FirstOrDefaultAsync();

    if (account != null)
    {
        var provider = string.IsNullOrWhiteSpace(account.AuthProvider)
            ? "password,google"
            : (account.AuthProvider.Contains("google") ? account.AuthProvider : account.AuthProvider + ",google");

        var update = Builders<CustomerAccount>.Update
            .Set(a => a.GoogleId, googleId)
            .Set(a => a.AuthProvider, provider)
            // Google-verified — clear any pending local verification too.
            .Set(a => a.EmailVerified, true)
            .Set(a => a.EmailVerificationToken, (string?)null)
            .Set(a => a.EmailVerificationExpiry, (DateTime?)null);
        await _accounts.UpdateOneAsync(a => a.Id == account.Id, update);

        account.GoogleId = googleId;
        account.AuthProvider = provider;
        account.EmailVerified = true;

        var t = GenerateJwt(account);
        return (t, account, false);
    }

    // (3) Brand-new account (sign-up). Auto-link to an existing CRM Client by
    // email (case-insensitive), mirroring RegisterAsync; otherwise create one.
    var linked = await _clients
        .Find(Builders<Client>.Filter.Regex(c => c.Email, emailPattern))
        .FirstOrDefaultAsync();

    string? clientId;
    if (linked != null)
    {
        clientId = linked.Id;
    }
    else
    {
        var newClient = new Client
        {
            FullName = string.IsNullOrWhiteSpace(fullName) ? email : fullName!,
            Email = email,
            ContactPlatform = "EMAIL"
        };
        await _clients.InsertOneAsync(newClient);
        clientId = newClient.Id;
    }

    var newAccount = new CustomerAccount
    {
        FullName = string.IsNullOrWhiteSpace(fullName) ? email : fullName!,
        Email = email,
        // Google-provisioned accounts have no user-chosen password. Store a
        // random, un-guessable BCrypt hash so the password-login path can
        // never succeed for them (and never NREs on a null hash) until the
        // user explicitly sets a password via the reset flow.
        PasswordHash = PasswordHasher.Hash(Guid.NewGuid().ToString("N") + Guid.NewGuid().ToString("N")),
        GoogleId = googleId,
        AuthProvider = "google",
        ClientId = clientId,
        EmailVerified = true,
        OnboardingCompleted = false
    };
    await _accounts.InsertOneAsync(newAccount);

    var token = GenerateJwt(newAccount);
    return (token, newAccount, true);
}

