/// <summary>
/// Self-gate probe. The login/register pages call this and only reveal the
/// "Continue with Google" button when it returns <c>enabled: true</c>, so the
/// feature ships dark until real Google credentials are configured.
/// </summary>
[HttpGet("google/enabled")]
[AllowAnonymous]
public IActionResult GoogleEnabled() => Ok(new { enabled = _google.IsConfigured });

// ── GET /api/customer/google/start ─────────────────────────────────────────
/// <summary>
/// Kicks off the Google authorization-code flow: sets a short-lived HttpOnly
/// CSRF nonce cookie and 302-redirects the browser to Google's consent
/// screen. No-ops with 404 when the feature isn't configured.
/// </summary>
[HttpGet("google/start")]
[AllowAnonymous]
[EnableRateLimiting("auth-login")]
public IActionResult GoogleStart([FromQuery] string? redirect)
{
    if (!_google.IsConfigured) return NotFound();

    var redirectUri = _google.ResolveRedirectUri(PublicOrigin());

    var nonce = Guid.NewGuid().ToString("N");
    var safeRedirect = SanitizeRedirect(redirect);
    var state = Base64UrlEncode(JsonSerializer.Serialize(new { n = nonce, r = safeRedirect }));

    Response.Cookies.Append("sp_goauth", nonce, new CookieOptions
    {
        HttpOnly = true,
        Secure = true,
        SameSite = SameSiteMode.Lax,
        MaxAge = TimeSpan.FromMinutes(10),
        Path = "/api/customer/google"
    });

    return Redirect(_google.BuildAuthorizationUrl(state, redirectUri));
}

// ── GET /api/customer/google/callback ──────────────────────────────────────
/// <summary>
/// Google redirects here with <c>code</c> + <c>state</c>. We validate the
/// CSRF nonce, exchange the code, sign-in-or-sign-up the customer, then
/// 302-redirect to the frontend <c>/auth/google</c> landing page carrying the
/// freshly minted JWT so the browser can store it and land logged in.
/// </summary>
[HttpGet("google/callback")]
[AllowAnonymous]
[EnableRateLimiting("auth-login")]
public async Task<IActionResult> GoogleCallback(
    [FromQuery] string? code,
    [FromQuery] string? state,
    [FromQuery] string? error,
    CancellationToken ct)
{
    if (!_google.IsConfigured) return NotFound();

    var frontend = FrontendBaseUrl();

    if (!string.IsNullOrWhiteSpace(error) || string.IsNullOrWhiteSpace(code) || string.IsNullOrWhiteSpace(state))
        return Redirect($"{frontend}/login?error=google");

    // Decode state → CSRF nonce + post-login redirect target.
    string nonce, redirectTarget;
    try
    {
        var el = JsonDocument.Parse(Encoding.UTF8.GetString(Base64UrlDecode(state))).RootElement;
        nonce = el.TryGetProperty("n", out var n) ? (n.GetString() ?? "") : "";
        redirectTarget = el.TryGetProperty("r", out var r) ? (r.GetString() ?? "") : "";
    }
    catch
    {
        return Redirect($"{frontend}/login?error=google");
    }

    var cookieNonce = Request.Cookies["sp_goauth"];
    Response.Cookies.Delete("sp_goauth", new CookieOptions { Path = "/api/customer/google" });
    if (string.IsNullOrEmpty(cookieNonce) || !string.Equals(cookieNonce, nonce, StringComparison.Ordinal))
        return Redirect($"{frontend}/login?error=google_state");

    var redirectUri = _google.ResolveRedirectUri(PublicOrigin());
    var info = await _google.ExchangeCodeAsync(code, redirectUri, ct);
    if (info == null)
        return Redirect($"{frontend}/login?error=google");

    try
    {
        var (token, account, isNew) = await _customerAuth.SignInWithGoogleAsync(
            info.Sub, info.Email, info.EmailVerified, info.Name);

        var url = $"{frontend}/auth/google" +
            $"?token={Uri.EscapeDataString(token)}" +
            $"&name={Uri.EscapeDataString(account.FullName ?? string.Empty)}" +
            $"&email={Uri.EscapeDataString(account.Email ?? string.Empty)}" +
            $"&clientId={Uri.EscapeDataString(account.ClientId ?? string.Empty)}" +
            $"&isNew={(isNew ? "1" : "0")}";
        if (!string.IsNullOrEmpty(redirectTarget))
            url += $"&redirect={Uri.EscapeDataString(redirectTarget)}";

        return Redirect(url);
    }
    catch
    {
        return Redirect($"{frontend}/login?error=google");
    }
}

// ── Google flow helpers ─────────────────────────────────────────────────────

/// <summary>Public HTTPS origin of the current request (honours the proxy's forwarded proto).</summary>
private string PublicOrigin() => $"{Request.Scheme}://{Request.Host}";

/// <summary>
/// Where to send the browser after the callback — the customer frontend.
/// Uses <c>PublicSite:BaseUrl</c> (the app's PUBLIC_APP_URL), falling back to
/// the request origin (frontend + API share the domain).
/// </summary>
private string FrontendBaseUrl()
{
    var configured = _config["PublicSite:BaseUrl"];
    return string.IsNullOrWhiteSpace(configured) ? PublicOrigin() : configured.TrimEnd('/');
}

/// <summary>Open-redirect guard: only allow same-site relative paths.</summary>
private static string SanitizeRedirect(string? redirect)
{
    if (string.IsNullOrWhiteSpace(redirect)) return "";
    if (!redirect.StartsWith("/") || redirect.StartsWith("//")) return "";
    return redirect;
}

private static string Base64UrlEncode(string s)
{
    var bytes = Encoding.UTF8.GetBytes(s);
    return Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
}

private static byte[] Base64UrlDecode(string input)
{
    var s = input.Replace('-', '+').Replace('_', '/');
    switch (s.Length % 4)
    {
        case 2: s += "=="; break;
        case 3: s += "="; break;
    }
    return Convert.FromBase64String(s);
}

