---
import '../../styles/customer.css';
// Google OAuth landing page. The backend /api/customer/google/callback
// redirects the browser here with a freshly minted JWT in the query string.
// We store it exactly like the password login flow does, then forward the user
// on. Rendered as a tiny "signing you in…" splash so the token is never left
// visible in the address bar for more than an instant (we replace() away).
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta name="robots" content="noindex" />
    <title>Signing you in… — Soul Pilates</title>
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
  </head>
  <body class="sp-customer">
    <div style="min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;background:var(--sp-bg);">
      <div class="sp-spinner" aria-hidden="true" style="width:38px;height:38px;border:3px solid rgba(0,0,0,0.1);border-top-color:var(--sp-brand,#c97b4b);border-radius:50%;animation:spgspin 0.8s linear infinite;"></div>
      <p class="sp-text-body sp-text-muted" id="spgMsg">Signing you in…</p>
    </div>

    <style is:global>
      @keyframes spgspin { to { transform: rotate(360deg); } }
    </style>

    <script is:inline>
      (function () {
        try {
          var qs = new URLSearchParams(window.location.search);
          var token = qs.get("token");
          if (!token) {
            window.location.replace("/login?error=google");
            return;
          }
          var isNew = qs.get("isNew") === "1";
          var redirect = qs.get("redirect") || "";

          localStorage.setItem("customer_token", token);
          localStorage.setItem("customer_name", qs.get("name") || "");
          localStorage.setItem("customer_email", qs.get("email") || "");
          localStorage.setItem("customer_clientId", qs.get("clientId") || "");

          // GA4: mirror the password flow's login/sign_up events.
          if (typeof window.spTrackEvent === "function") {
            window.spTrackEvent(isNew ? "sign_up" : "login", {
              method: "google",
              page: "google_callback",
            });
          }

          // Only honour same-site relative redirect targets (open-redirect guard).
          var dest;
          if (redirect && redirect.charAt(0) === "/" && redirect.charAt(1) !== "/") {
            dest = redirect;
          } else if (isNew) {
            dest = "/onboarding";
          } else {
            dest = "/account";
          }
          window.location.replace(dest);
        } catch (e) {
          window.location.replace("/login?error=google");
        }
      })();
    </script>

    <!-- GA4 loader (standalone page) so the sign_up/login event can fire. -->
    <script is:inline>
      (function () {
        fetch("/api/analytics/ga-config")
          .then(function (r) { return r.ok ? r.json() : null; })
          .then(function (cfg) {
            if (!cfg || !cfg.measurementId) return;
            var s = document.createElement("script");
            s.async = true;
            s.src = "https://www.googletagmanager.com/gtag/js?id=" + cfg.measurementId;
            document.head.appendChild(s);
            window.dataLayer = window.dataLayer || [];
            function gtag() { window.dataLayer.push(arguments); }
            window.gtag = gtag;
            gtag("js", new Date());
            gtag("config", cfg.measurementId, { send_page_view: false });
          })
          .catch(function () {});
      })();
    </script>
  </body>
</html>
